    id: 38,
    title: "Anne Frank and the Holocaust",
    cefr: "B1",
    theme: "Past Simple Biography",
    paragraphs: [
      "The Holocaust was when Nazi Germany killed Jewish people during World War II (WW2). Almost six million Jews were killed. Anne Frank is one of the most famous Jewish people who died in the Holocaust. Her diary, which is one of the most popular books today, is seen as a classic in war literature. There are many plays and movies about the diary.",
      "Frank was the second daughter of Otto Frank, a German businessman, and Edith Frank-Hollander. The Franks were Jews who lived with many Jewish and non-Jewish citizens. Anne and her older sister Margot grew up with Catholic, Protestant, and Jewish friends. Their mother was very religious, but their father was more interested in studying. Their father, who had a large library, wanted his children to read like him.",
      "The Nazis became powerful in Germany in 1933. The Franks were afraid of the Nazis and didn't want to stay in Germany. So later that year, Edith and the children went to Aachen. They stayed there with Edith's mother, Rosa Hollander. Otto continued to live in Frankfurt, but later he moved to Amsterdam to begin a business and find a place to live with his family.",
      "Anne and Margot began going to school. Margot went to a public school and Anne went to a Montessori school. Margot liked maths, and Anne enjoyed reading and writing. Anne often wrote, but she tried to hide her writings and did not like talking about them. Margot and Anne had very different personalities. Margot was polite, quiet, and thoughtful, but Anne was brave, energetic, and friendly.",
    ],
