    cefr: "C1",
    theme: "Conditionals & Vocabulary",
    paragraphs: [
      "If we tried to, could we really transform the frozen surface of Mars into something more friendly - a place where humans could live? And equally importantly, should we? The first question has a clear answer: Yes, we probably could. NASA planetary scientist Chris McKay says, 'Most of the work in \"terraforming\" (making it similar to Earth) would be done by life itself. We wouldn't have to build Mars, just modify its atmosphere.' 'If we warmed it up and threw in some seeds, plants would grow there.'",
      "Robert Zubrin, an engineer and president of the Mars Society, dreams of Martian cities. He thinks one day, we will have urban areas on Mars! Zubrin believes civilisation cannot succeed if it doesn't expand limitlessly. He also thinks that if we transformed Mars, we might learn to manage our limited Earth better. He also says, if he was an astronaut, he wouldn't volunteer for that six-month journey!",
      "YEAR ZERO: The thousand-year project might begin with a series of eighteen-month survey missions. Each crew member who makes the six-month journey from Earth to Mars would add a small habitation module to the base. 100 YEARS: We could make an Earth-like atmosphere. First, we would release the carbon dioxide which is now frozen in the ice. Maybe mirrors could focus sunlight on the ice to do this.",
    ],
