    id: 71,
    title: "Bollywood and Hollywood",
    cefr: "B2",
    theme: "Comparison & Vocabulary",
    paragraphs: [
      "Bollywood and Hollywood are two internationally recognized film industries. Hollywood is basically the American film industry, distributing movies worldwide. It's named after a district in California which became the centre of movie studios in the early 1900s. It was established before WWI and is considered to be the world's leading and influential industry. Both Hollywood movies and Bollywood movies are recognized by many people around the world.",
      "Hollywood movies are made on a large budget. They usually involve elements of blood, action and other controversial themes. In terms of revenue, Hollywood dominates the sales. The industry earns money by utilising a franchise system apart from revenue from the actual film. A movie is often tied with various other media, such as TV networks and magazines. In terms of worldwide cinema, Hollywood gets around 75 per cent of all movie revenues.",
      "On the other hand, Bollywood is the Hindi cinema industry. The term was coined and popularized during the time when Hindi cinema surpassed Hollywood in the number of films produced. The name is a combination of Bombay and Hollywood. Movies created by Bollywood are often family-oriented and appeal to human sensitivity. The dominant themes in these movies are musicals with large casts and song-and-dance sequences. A major criticism of Bollywood movies is that they have a predictable and consistent plot. However, these plots show creativity and a form of escapist entertainment. Another criticism is that Bollywood replicates plots from Hollywood movies.",
    ],
