    id: 99,
    title: "Sugar: A Bittersweet History",
    cefr: "C1",
    theme: "Reading Comprehension (YDS)",
    paragraphs: [
      "Today sugar makes almost any food seductive and irresistible in taste. But in the past it led to more than that, as it was not as white as it seemed. While sugar would bring wealth and independence to some, it would also bring misery, slavery and wrath to many others. Profit from the sugar trade was so significant that it may have even helped America achieve independence from Great Britain.",
      "Sugar, which British colonists called 'White Gold', was the engine of the slave trade that brought millions of Africans to the Americas in the early 16th century. Though the Dutch and the Portuguese predated other European colonizers in the slave trade, it was the British and the Spanish that pioneered the affair. The demand for sugar in Europe and Asia reached such a height that the European colonizers had a hard time compensating for the production due to the lack of labor.",
      "As the Spanish had almost wiped out the entire population of the West Indies and South America, labor had to be imported so as to keep up with the production of commodities such as sugar, tobacco and other crops, not to mention gold. It is impossible to think about sugar production in the West Indies without thinking about slavery. The labor of enslaved Africans was integral to the cultivation of the cane and the production of sugar. So, when you add some sugar to your tea, keep the history behind it in your mind.",
    ],
