    theme: "Reading Comprehension (YDS)",
    paragraphs: [
      "Drinking tea is actually drinking a lot of history. Tea has been one of the most widespread beverages around the globe, with a very distant past. The British, for example, had a good appetite for tea. Although the earliest custom of drinking tea dates back to the third millennium BC in China, it was not until the mid-17th century that the beverage first appeared in England.",
      "Once tea caught on, Britain had to import as much tea as they could from around the world. And this meant they had to pour a fortune into buying tea, which would soon cause various conflicts. For example, in an incident known as the 'Boston Tea Party', the tea-drinking Americans protested both the tax on tea and the perceived monopoly of Britain over tea and other commodities. This would soon lead to the liberation and foundation of the United States.",
      "China was another main source of tea, but China would only accept silver as payment for its tea, due to which the British had to pour an immense amount of silver into China. This placed a toll on the British economy, so they then began to remedy the financial debt by trading opium to China, instead of silver. This opium trade paid for the tea exported from China, and soon money was flowing out of China to Britain, which would cause the wars known as 'The Opium Wars' and the defeat of China. So when you have a cup of tea, remember that you are actually consuming history.",
    ],
